import React, { useState, useEffect } from 'react';

const ProductModal = ({ isOpen, onClose, onSubmit, initialData }) => {
    const [formData, setFormData] = useState({
        title: '', category: 'GPU', price: '', description: '', stock: '0', image: ''
    });

    useEffect(() => {
        if (initialData) setFormData(initialData);
        else setFormData({ title: '', category: 'GPU', price: '', description: '', stock: '0', image: '' });
    }, [initialData, isOpen]);

    if (!isOpen) return null;

    return (
        <div className="modal-overlay">
            <div className="modal-content">
                <h2>{initialData ? 'Редактировать' : 'Добавить товар'}</h2>
                <form onSubmit={(e) => { e.preventDefault(); onSubmit(formData); }}>
                    <input 
                        type="text" placeholder="Название" required
                        value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} 
                    />
                    <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                        <option value="GPU">GPU</option>
                        <option value="CPU">CPU</option>
                        <option value="RAM">RAM</option>
                        <option value="SSD">SSD</option>
                    </select>
                    <input 
                        type="number" placeholder="Цена" required
                        value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} 
                    />
                    {/* Поле для "загрузки" фото (путь к файлу) */}
                    <div className="file-input-group">
                        <label>Имя файла в /public/images/ (напр. gpu.png):</label>
                        <input 
                            type="text" 
                            value={formData.image} 
                            placeholder="/images/example.png"
                            onChange={e => setFormData({...formData, image: e.target.value})} 
                        />
                    </div>
                    <textarea 
                        placeholder="Описание" 
                        value={formData.description} 
                        onChange={e => setFormData({...formData, description: e.target.value})}
                    />
                    <div className="modal-actions">
                        <button type="button" onClick={onClose}>Отмена</button>
                        <button type="submit" className="save-btn">Сохранить</button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default ProductModal;
